#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int ll_record;
static void ll_require(bool condition,const char *label){if(!condition){fprintf(stderr,"last-login record%d: %s\n",ll_record,label);exit(3);}}
static int ll_int(FILE *f){uint8_t b[4];ll_require(fread(b,1,4,f)==4,"fixture integer");return (int32_t)((uint32_t)b[0]<<24|(uint32_t)b[1]<<16|(uint32_t)b[2]<<8|b[3]);}
static bool ll_bool(FILE *f){int value=fgetc(f);ll_require(value==0 || value==1,"fixture boolean");return value!=0;}
static void ll_string(FILE *f,char *text,size_t capacity){int n=ll_int(f);ll_require(n>=0 && (size_t)n<capacity && fread(text,1,(size_t)n,f)==(size_t)n,"fixture string");text[n]=0;}
static void ll_dns_string(FILE *f,char *text,size_t capacity){int n=ll_int(f);if(n==-1){text[0]=0;return;}ll_require(n>=0 && (size_t)n<capacity && fread(text,1,(size_t)n,f)==(size_t)n,"nullable DNS string");text[n]=0;}
static void ll_dns_text(FILE *f,const char *actual){char expected[256];ll_dns_string(f,expected,sizeof(expected));ll_require(!strcmp(actual,expected),"nullable DNS state");}
static void ll_text(FILE *f,const char *actual){char expected[512];ll_string(f,expected,sizeof(expected));ll_require(actual && !strcmp(actual,expected),"text state");}
static void ll_eq(FILE *f,int actual,const char *label){int expected=ll_int(f);if(expected!=actual){fprintf(stderr,"last-login record%d %s expected%d actual%d\n",ll_record,label,expected,actual);exit(3);}}
static void ll_cipher(FILE *f,const Isaac *cipher){ll_eq(f,cipher->count,"cipher count");ll_eq(f,(int32_t)cipher->a,"cipher a");ll_eq(f,(int32_t)cipher->b,"cipher b");ll_eq(f,(int32_t)cipher->c,"cipher c");for(int i=0;i<256;i++)ll_eq(f,(int32_t)cipher->rsl[i],"cipher rsl");for(int i=0;i<256;i++)ll_eq(f,(int32_t)cipher->mem[i],"cipher mem");}
typedef struct {
    void (*packet)(const uint8_t*,size_t);
    void (*wire)(GameSession*,int);
    void (*picture)(int,const uint32_t*,int);
} LastLoginHooks225;
static void ll_layout(ComponentConfig *cfg,int mode,int target){if(mode==1)for(int i=0;i<cfg->count;i++)if(cfg->instances[i].client_code==target)cfg->instances[i].client_code=0;
    if(mode==2){int found=0;for(int i=0;i<cfg->count && found<2;i++)if(cfg->instances[i].width || cfg->instances[i].height || cfg->instances[i].child_count){cfg->instances[i].client_code=target;cfg->instances[i].layer=1234+found++;}}
}
static void last_login_reference_run(const char *path,const char *ui_path,ComponentConfig *cfg,
    LastLoginInfo225 *info,InterfaceState *state,Chatbox *chat,GameSession *session,const LastLoginHooks225 *hooks){
    FILE *f=fopen(path,"rb");ll_require(f && ll_int(f)==0x4c4c3235,"original fixture");int count=ll_int(f);ll_require(count==2406,"case count");uint32_t seed[4];for(int i=0;i<4;i++)seed[i]=(uint32_t)ll_int(f);int ids[6],roots[2];Component probes[6]={0};uint32_t colours[6];for(int i=0;i<6;i++){ids[i]=ll_int(f);Component *v=ids[i]>=0?component_get(cfg,ids[i]):&probes[i];ll_require(v!=NULL,"cached/probe component");v->client_code=650+i;colours[i]=v->colour;}for(int i=0;i<2;i++)roots[i]=ll_int(f);
    int *codes=malloc((size_t)cfg->count*sizeof(int)),*layers=malloc((size_t)cfg->count*sizeof(int));ll_require(codes && layers,"layout allocation");for(int i=0;i<cfg->count;i++){codes[i]=cfg->instances[i].client_code;layers[i]=cfg->instances[i].layer;}
    isaac_init(&session->out_cipher,seed,4);session->in_game=true;session->stream.buffered=true;int opened=0;
    for(ll_record=0;ll_record<count;ll_record++){
        uint8_t payload[9];ll_require(fread(payload,1,9,f)==9,"input payload");state->viewport=ll_int(f);state->sidebar=ll_int(f);state->chat=ll_int(f);int mode=ll_int(f);ll_dns_string(f,info->dns,sizeof(info->dns));strcpy(info->dns_request,"127.0.0.9");chat->report_interface=77;strcpy(chat->report_input,"Report kept");chat->report_mute=true;chat->count_dialog_open=true;strcpy(chat->count_dialog_input,"42");chat->private_prompt_open=true;strcpy(chat->private_input,"social kept");strcpy(chat->input,"ordinary kept");Chatbox before=*chat;session->stream.out_len=0;
        ll_layout(cfg,mode,payload[6]==201?650:655);if(hooks && hooks->packet)hooks->packet(payload,9);else ll_require(last_login_receive225(info,state,chat,cfg,session,payload,9)>0,"native packet application");
        ll_eq(f,(int32_t)info->last_address,"last address");ll_eq(f,info->days_since_login,"login days");ll_eq(f,info->days_since_recovery,"recovery days");ll_eq(f,info->unread_messages,"unread");ll_eq(f,state->viewport,"viewport");ll_eq(f,state->sidebar,"sidebar");ll_eq(f,state->chat,"chat interface");ll_eq(f,chat->report_interface,"report interface");ll_text(f,chat->report_input);ll_require(ll_bool(f)==chat->report_mute,"report mute");ll_require(ll_bool(f)==chat->count_dialog_open,"count open");ll_text(f,chat->count_dialog_input);ll_require(ll_bool(f)==chat->private_prompt_open,"social prompt");ll_text(f,chat->private_input);ll_text(f,chat->input);ll_dns_text(f,info->dns);ll_text(f,info->dns_request);
        /* Original redraw flags/pressedContinue metadata lack a native equivalent.
         * Retain the four captured fields without promoting them to acceptance. */
        for(int i=0;i<4;i++)(void)ll_bool(f);
        int wire=ll_int(f);ll_require(wire==0 || wire==1,"close wire size");uint8_t expected=0;if(wire)ll_require(fread(&expected,1,1,f)==1,"wire byte");if(hooks && hooks->wire)hooks->wire(session,wire);ll_require(session->stream.out_len==(size_t)wire && (!wire || session->stream.out_buf[0]==expected),"encrypted close231");ll_cipher(f,&session->out_cipher);if(wire){opened++;before.report_input[0]=0;before.report_mute=false;}ll_require(!memcmp(chat,&before,sizeof(*chat)),"unrelated chat state retained");
        for(int i=0;i<cfg->count;i++){cfg->instances[i].client_code=codes[i];cfg->instances[i].layer=layers[i];}
        for(int i=0;i<6;i++){Component *v=ids[i]>=0?component_get(cfg,ids[i]):&probes[i];v->text="old text";v->colour=0x102030u+(unsigned)i;last_login_prepare225(info,v);ll_text(f,v->text);ll_eq(f,(int)v->colour,"content colour");}
    }
    ll_require(opened==678 && fgetc(f)==EOF,"capture count/tail");fclose(f);free(codes);free(layers);for(int i=0;i<6;i++){Component *v=ids[i]>=0?component_get(cfg,ids[i]):&probes[i];v->colour=colours[i];}
    f=fopen(ui_path,"rb");ll_require(f && ll_int(f)==0x4c553235 && ll_int(f)==24,"UI fixture");for(int i=0;i<2;i++)ll_eq(f,roots[i],"UI roots");uint32_t *pixels=calloc(512*334+2,sizeof(*pixels)),*expected=malloc(512*334*sizeof(*expected));ll_require(pixels && expected,"UI allocations");
    for(ll_record=0;ll_record<24;ll_record++){
        info->last_address=(uint32_t)ll_int(f);info->days_since_login=ll_int(f);info->days_since_recovery=ll_int(f);info->unread_messages=ll_int(f);int root=ll_int(f);ll_string(f,info->dns,sizeof(info->dns));for(int i=0;i<512*334;i++)expected[i]=(uint32_t)ll_int(f);for(int i=0;i<cfg->count;i++)last_login_prepare225(info,&cfg->instances[i]);memset(pixels+1,0,512*334*sizeof(*pixels));pixels[0]=pixels[512*334+1]=0xDEADBEEF;pix2d_bind(pixels+1,512,334);component_draw(cfg,component_get(cfg,root),0,0,0);for(int i=0;i<512*334;i++){if(pixels[i+1]!=expected[i]){fprintf(stderr,"last-login panel%d pixel%d actual%x expected%x\n",ll_record,i,pixels[i+1],expected[i]);exit(3);}}ll_require(pixels[0]==0xDEADBEEF && pixels[512*334+1]==0xDEADBEEF,"pixel guards");if(hooks && hooks->picture)hooks->picture(root,expected,ll_record);
    }
    ll_require(fgetc(f)==EOF,"UI tail");fclose(f);free(pixels);free(expected);puts("PASS last-login original:2406 read140 states,678 close231 observations;full stored fields/interfaces/report/input/DNS/wire/ISAAC;6 content text/colour controls (3 cache widgets,3 direct probes);24 complete512x334 panels/4104192 pixels and guards;redraw/continue metadata unqualified");
}
static void last_login_fault_controls(void){
    LastLoginInfo225 info={0},before_info;InterfaceState state={-1,55,27},before_state=state;Chatbox *chat=calloc(1,sizeof(*chat)),*before_chat=calloc(1,sizeof(*chat));GameSession *session=calloc(1,sizeof(*session)),*before_session=calloc(1,sizeof(*session));ll_require(chat && before_chat && session && before_session,"failure allocations");Component widgets[2]={{.client_code=650,.layer=5993},{.client_code=655,.layer=6073}};ComponentConfig cfg={.count=2,.instances=widgets};protocol_init_session(session);session->in_game=true;session->stream.buffered=true;uint32_t seed[]={225,140,650,655};isaac_init(&session->out_cipher,seed,4);strcpy(chat->report_input,"retained report");chat->report_mute=true;strcpy(info.dns,"prior.example");strcpy(info.dns_request,"127.0.0.9");info.dns_generation=7;before_info=info;*before_chat=*chat;*before_session=*session;uint8_t payload[18]={192,0,2,1,255,255,201,255,255};int malformed=0;
    for(size_t n=0;n<=18;n++)if(n!=9){ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,n)==-1 && !memcmp(&info,&before_info,sizeof(info)) && !memcmp(&state,&before_state,sizeof(state)) && !memcmp(chat,before_chat,sizeof(*chat)) && !memcmp(session,before_session,sizeof(*session)),"malformed packet transactional");malformed++;}
    ll_require(last_login_receive225(&info,&state,chat,&cfg,session,NULL,9)==-1,"null payload");malformed++;
    ll_require(last_login_receive225(NULL,&state,chat,&cfg,session,payload,9)==-1 && last_login_receive225(&info,NULL,chat,&cfg,session,payload,9)==-1 && last_login_receive225(&info,&state,NULL,&cfg,session,payload,9)==-1 && last_login_receive225(&info,&state,chat,NULL,session,payload,9)==-1 && last_login_receive225(&info,&state,chat,&cfg,NULL,payload,9)==-1,"null metadata");malformed+=5;cfg.count=-1;ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,9)==-1,"negative component count");cfg.count=1;cfg.instances=NULL;ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,9)==-1,"null component storage");cfg.count=2;cfg.instances=widgets;malformed+=2;
    session->stream.out_len=5000;memset(session->stream.out_buf,0xA5,5000);Isaac cipher=session->out_cipher;ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,9)==-2 && info.last_address==0xC0000201u && info.days_since_login==65535 && info.days_since_recovery==201 && info.unread_messages==65535 && !strcmp(info.dns,"192.0.2.1") && info.dns_generation==8,"source stored fields andDNS precede close failure");ll_require(session->stream.out_overflow && !memcmp(&cipher,&session->out_cipher,sizeof(cipher)) && session->stream.out_len==5000 && !memcmp(&state,&before_state,sizeof(state)) && !memcmp(chat,before_chat,sizeof(*chat)),"capacity preserves cipher/UI");for(int i=0;i<5000;i++)ll_require(session->stream.out_buf[i]==0xA5,"capacity bytes retained");
    session->stream.out_len=0;ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,9)==-2 && !memcmp(&cipher,&session->out_cipher,sizeof(cipher)),"sticky overflow");session->stream.out_overflow=false;session->stream.buffered=false;session->stream.connected=false;ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,9)==-2 && !memcmp(&cipher,&session->out_cipher,sizeof(cipher)) && !memcmp(&state,&before_state,sizeof(state)),"disconnected close preserves cipher/UI");session->stream.buffered=true;session->stream.out_len=4999;ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,9)==2 && session->stream.out_len==5000 && state.viewport==5993 && state.sidebar==-1 && state.chat==-1 && !chat->report_input[0] && !chat->report_mute,"exact one-byte capacity recovery");
    state=(InterfaceState){-1,55,27};session->stream.out_overflow=true;uint64_t generation=info.dns_generation;payload[0]=payload[1]=payload[2]=payload[3]=0;ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,9)==1 && !memcmp(&state,&before_state,sizeof(state)) && info.dns_generation==generation,"zero address suppresses close andDNS even onoverflow");payload[0]=192;payload[2]=2;payload[3]=1;state.viewport=42;ll_require(last_login_receive225(&info,&state,chat,&cfg,session,payload,9)==1 && state.viewport==42 && info.dns_generation==generation,"existing viewport suppresses close andDNS");Component other={.client_code=649,.text="keep",.colour=123};last_login_prepare225(NULL,&other);last_login_prepare225(&info,NULL);last_login_prepare225(&info,&other);ll_require(!strcmp(other.text,"keep") && other.colour==123,"unrelated clientcode retained");other.client_code=656;last_login_prepare225(&info,&other);ll_require(!strcmp(other.text,"keep") && other.colour==123,"high unrelated clientcode retained");
    free(chat);free(before_chat);free(session);free(before_session);printf("PASS last-login failures:%d malformed/null/metadata guards;capacity/sticky/disconnected output cipher andUI retention,exact one-byte recovery,zero-address/existing-viewport suppression;source field/DNS-before-close order;unrelated content guards\n",malformed);
}
static void last_login_registered_reference(ComponentConfig *cfg){static LastLoginInfo225 info;InterfaceState state;Chatbox *chat=calloc(1,sizeof(*chat));GameSession *session=calloc(1,sizeof(*session));ll_require(chat && session,"registered state allocation");protocol_init_session(session);const char *path=getenv("RS2_LAST_LOGIN_ORACLE"),*ui=getenv("RS2_LAST_LOGIN_UI_ORACLE");last_login_reference_run(path && *path?path:"tests/fixtures/last-login-reference.bin",ui && *ui?ui:"tests/fixtures/last-login-ui.bin",cfg,&info,&state,chat,session,NULL);free(chat);free(session);last_login_fault_controls();}
